tool_calls.arguments:
{"command":"cat > tmp.json <<'EOF';
{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "image": "nginx:1.31.5",
            "imagePullPolicy": "IfNotPresent",
            "ports": [
              {"name": "http", "protocol": "TCP", "containerPort": 80}
            ],
            "readinessProbe": {
              "httpGet": {"path": "/","port": 80,"scheme": "HTTP"},
              "failureThreshold": 3,"periodSeconds": 2,"timeoutSeconds": 10000
            },
            "startupProbe": {
              "exec": {"command": ["/usr/sbin/nginx","-v"]},
              "initialDelaySeconds": 15,
              "periodSeconds": 2,
              "timeoutSeconds": 10000,
              "failureThreshold": 3
            }
          }
        ]
      }
    }
  }
}
EOF
kubectl patch deploy app -n default --type strategic -p "$(python3 -m json.tool tmp.json 2>&1 | python3 -m json.tool --json-indent 2)"
echo "---"; kubectl get deploy app -n default -o jsonpath='{range .status.conditions[*]}{.type}={.status} {.reason} {.message}{"\n"}{end}'; echo "---"; kubectl get deploy app -n default"}

